CE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(STYLE)) LIKE \'%TECHNICAL%\' THEN \'TECHNICAL\' WHEN UPPER(TRIM(DESIGNS)) = \'SOLID\' THEN \'CORE\' ELSE \'FASHION\' END WHEN UPPER(CATEGORY) = \'SHIRTS\' THEN CASE WHEN UPPER(TRIM(DESIGNS)) = \'SOLID\' THEN \'SOLID\' WHEN UPPER(TRIM(DESIGNS)) = \'STRIPES\' THEN \'STRIPES\' ELSE \'PRINTED\' END END ), \'NA\') AS META2, COALESCE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(FIT)) IN (\'OVERSIZED\',\'BOX FIT\',\'RELAXED FIT\') THEN \'OVERSIZED FIT\' WHEN UPPER(TRIM(FIT)) = \'SLIM FIT\' THEN \'SLIM FIT\' ELSE \'REGULAR FIT\' END END ), \'NA\') AS META3 FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), CLEAN_AVAILABILITY AS ( SELECT M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3, CAST(A.PRICE AS NUMBER(10,2)) AS PRICE FROM SNITCH_DB.MAPLEMONK.AVAILABILITY_MASTER_V2 A INNER JOIN SKU_META_MASTER M ON REGEXP_REPLACE(UPPER(TRIM(A.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = M.CLEAN_SKU_GROUP WHERE A.PRICE IS NOT NULL AND A.PRICE > 0 ), CAT_BOUNDS AS ( SELECT CATEGORY, STYLE, META1, META2, META3, FLOOR(MIN(PRICE) / 200) * 200 AS START_PRICE, CEIL(MAX(PRICE) / 200) * 200 AS END_PRICE FROM CLEAN_AVAILABILITY GROUP BY CATEGORY, STYLE, META1, META2, META3 ), SLAB_GENERATOR AS ( SELECT C.CATEGORY, C.STYLE, C.META1, C.META2, C.META3, SEQ.SEQ + 1 AS SLAB_NUMBER, CONCAT(\'SLAB_\', SEQ.SEQ + 1) AS PRICE_SLAB_CODE, (C.START_PRICE + (SEQ.SEQ * 200)) AS SLAB_MIN_PRICE, (C.START_PRICE + (SEQ.SEQ * 200) + 199) AS SLAB_MAX_PRICE FROM CAT_BOUNDS C JOIN ( SELECT ROW_NUMBER() OVER (ORDER BY NULL) - 1 AS SEQ FROM TABLE(GENERATOR(ROWCOUNT => 100)) ) SEQ ON (C.START_PRICE + (SEQ.SEQ * 200)) < C.END_PRICE ) SELECT CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, SLAB_MIN_PRICE, SLAB_MAX_PRICE, CONCAT(\'₹\', SLAB_MIN_PRICE, \' – ₹\', SLAB_MAX_PRICE) AS PRICE_RANGE_LABEL, CURRENT_TIMESTAMP() AS UPDATED_AT FROM SLAB_GENERATOR ORDER BY CATEGORY, STYLE, META1, META2, META3, SLAB_MIN_PRICE;",
